interface Quote {
  id: string;
  text: string;
  author?: string;
  source?: string;
  difficulty: 'easy' | 'medium' | 'hard';
  length: number; // character count
  category?: string;
  createdAt: Timestamp;
}

type Props = {
  text: string;
  typed: string;
  status: AppStatus;
  onType: (value: string) => void;
  actions?: React.ReactNode;
  className?: string;
};

interface TypingEngineProps {
  targetText: string;
  onSessionComplete: (session: TypingSession) => void;
  duration?: number;
  enabled?: boolean;
  onTimerStart?: () => void;
  onTimerPause?: () => void;
  onTimerResume?: () => void;
  onTimerComplete?: () => void;
}
